mapper.select:
        select * from fitian.Record
		where wodNo = #{wodNo}
		order by field(level, 'Rx\'d', 'A', 'B','C'), round desc, reps desc, field(result, 'success','fail'), team

mapper.update:
update fitian.Record
SET level=#{level}, round=#{round}, reps=#{reps}, time=#{time}, result=#{result}, team=#{team}, memo=#{memo}, classTime=#{classTime},
where recordNo = #{recordNo}

update fitian.Record
SET useYN = "N"
where recordNo = #{recordNo}
